describe('getUser (regenerated)', () => {
  it('encodes the id before building the URL', async () => {
    const mockFetch = jest.spyOn(global, 'fetch').mockResolvedValue({
      ok: true,
      json: async () => ({})
    } as any)

    await getUser('a/b')

    expect(mockFetch).toHaveBeenCalledWith('https://api.example.com/user/a%2Fb')
  })
})

